using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class RepairCompleteTrees {
class Tree {public string id;public Vector3 p;}
class Batch {public string id;public Mesh mesh;public string path;public Matrix4x4 matrix;public string name;}
static string Id(Object o){var id=GlobalObjectId.GetGlobalObjectIdSlow(o);return id.targetObjectId+"-"+id.targetPrefabId;}
static bool TreeCollider(Collider c)=>c.name.IndexOf("tree",StringComparison.OrdinalIgnoreCase)>=0||c.name.IndexOf("trunk",StringComparison.OrdinalIgnoreCase)>=0;
static bool TreeMesh(MeshFilter m)=>m.sharedMesh&&m.GetComponent<Renderer>()&&(m.GetComponentsInParent<Transform>().Any(t=>t.name.IndexOf("woods",StringComparison.OrdinalIgnoreCase)>=0||t.name.Contains("Forest tree"))||m.name=="Additional woodland canopy");
public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");EditorApplication.delayCall+=()=>{const string temp="Assets/Track/BackyardReverse/TemporaryOriginalTrees.unity";var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;var rows=new List<string>();try{
foreach(var scene in Racer.RacePlaylists.Scenes){File.AppendAllText("Docs/BackyardReverse/complete-tree-progress.txt",scene+" starting\n");var source=scene=="DansBackyardReverse"?"DansBackyardForward":scene;File.Copy("Temp/BackyardTreeBaselines/"+source+".unity",temp,true);AssetDatabase.ImportAsset(temp,ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.OpenScene(temp);Physics.SyncTransforms();
var trees=Object.FindObjectsByType<Collider>().Where(TreeCollider).Select(c=>new Tree{id=Id(c),p=c.bounds.center}).ToArray();
var cells=trees.GroupBy(t=>new Vector2Int(Mathf.FloorToInt(t.p.x/8),Mathf.FloorToInt(t.p.z/8))).ToDictionary(g=>g.Key,g=>g.ToArray());
var batches=Object.FindObjectsByType<MeshFilter>().Where(TreeMesh).Select(m=>new Batch{id=Id(m),path=AssetDatabase.GetAssetPath(m.sharedMesh),matrix=m.transform.localToWorldMatrix,name=m.name}).ToArray();
EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");Physics.SyncTransforms();var current=Object.FindObjectsByType<Collider>().Where(TreeCollider).ToDictionary(Id,c=>c.bounds.center);var currentMeshes=Object.FindObjectsByType<MeshFilter>().ToDictionary(Id,m=>m);int removed=0,moved=0,edited=0;
foreach(var b in batches){if(!currentMeshes.TryGetValue(b.id,out var mf))continue;b.mesh=Object.Instantiate(AssetDatabase.LoadAssetAtPath<Mesh>(b.path));var v=b.mesh.vertices;var ts=b.mesh.triangles;var used=ts.Distinct().ToArray();var parents=Enumerable.Range(0,v.Length).ToArray();int F(int i){while(parents[i]!=i){parents[i]=parents[parents[i]];i=parents[i];}return i;}void J(int a,int d){parents[F(a)]=F(d);}var weld=new Dictionary<Vector3Int,int>();foreach(int i in used){var key=Vector3Int.RoundToInt(v[i]*1000);if(weld.TryGetValue(key,out int o))J(i,o);else weld[key]=i;}for(int i=0;i<ts.Length;i+=3){J(ts[i],ts[i+1]);J(ts[i],ts[i+2]);}
var cuts=new HashSet<int>();var moves=new Dictionary<int,float>();foreach(var g in used.GroupBy(F)){var bound=new Bounds(b.matrix.MultiplyPoint3x4(v[g.First()]),Vector3.zero);foreach(int i in g)bound.Encapsulate(b.matrix.MultiplyPoint3x4(v[i]));var p=bound.center;var cell=new Vector2Int(Mathf.FloorToInt(p.x/8),Mathf.FloorToInt(p.z/8));Tree owner=null;float best=36;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){if(!cells.TryGetValue(cell+new Vector2Int(x,z),out var list))continue;foreach(var t in list){float d=(new Vector2(p.x-t.p.x,p.z-t.p.z)).sqrMagnitude;if(d<best){best=d;owner=t;}}}if(owner==null)continue;if(!current.TryGetValue(owner.id,out var cp)){cuts.Add(g.Key);removed++;}else if(Math.Abs(cp.y-owner.p.y)>.02f){moves[g.Key]=cp.y-owner.p.y;moved++;}}
if(cuts.Count+moves.Count==0){Object.DestroyImmediate(b.mesh);continue;}for(int i=0;i<v.Length;i++)if(moves.TryGetValue(F(i),out float dy))v[i]+=b.matrix.inverse.MultiplyVector(Vector3.up*dy);var kept=new List<int>();for(int i=0;i<ts.Length;i+=3)if(!cuts.Contains(F(ts[i])))kept.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});b.mesh.vertices=v;b.mesh.triangles=kept.ToArray();b.mesh.RecalculateBounds();b.mesh.hideFlags=HideFlags.None;AssetDatabase.CreateAsset(b.mesh,AssetDatabase.GenerateUniqueAssetPath("Assets/Track/BackyardReverse/CompleteTrees-"+scene+"-"+b.id+".asset"));mf.sharedMesh=b.mesh;if(mf.GetComponent<MeshCollider>())mf.GetComponent<MeshCollider>().sharedMesh=b.mesh;edited++;}
EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();rows.Add(scene+": render pieces removed="+removed+", vertically aligned="+moved+", batches="+edited+"; ownership resolved against original pre-task trunks before removals");File.WriteAllLines("Docs/BackyardReverse/complete-tree-repair.txt",rows);
}AssetDatabase.DeleteAsset(temp);File.WriteAllText("Docs/BackyardReverse/complete-tree-done.txt","Whole multi-crown trees reconciled with current physical trunks.");}catch(Exception e){File.WriteAllText("Docs/BackyardReverse/complete-tree-error.txt",e.ToString());}finally{EditorSceneManager.OpenScene(original);}};return "Repair complete tree batches from preserved original geometry and current trunks";}}


